  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "ViewCalendarEvent",
        "params": {
          "entityId": "evt-main-001"
        }
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "countdown": {
        "daysText": {
          "type": "string",
          "description": "距离活动开始的动态剩余天数展示文本，由端侧按日期每日更新。",
          "sampleValue": "3天"
        }
      },
      "calendar": {
        "items": [
          {
            "entityId": {
              "type": "string",
              "description": "日程项唯一标识符，用于打开对应日程详情。",
              "sampleValue": "evt-main-001"
            },
            "title": {
              "type": "string",
              "description": "日程标题。",
              "sampleValue": "项目评审会"
            },
            "dtStart": {
              "type": "string",
              "description": "日程开始时间，当天事件为 HH:MM 格式。",
              "sampleValue": "09:30"
            },
            "dtEnd": {
              "type": "string",
              "description": "日程结束时间，当天事件为 HH:MM 格式。",
              "sampleValue": "10:30"
            },
            "eventLocation": {
              "type": "string",
              "description": "日程发生的位置。",
              "sampleValue": "A座 3F 会议室"
            }
          },
          {
            "entityId": {
              "type": "string",
              "description": "第二条日程项唯一标识符。",
              "sampleValue": "evt-sub-002"
            },
            "title": {
              "type": "string",
              "description": "第二条日程标题。",
              "sampleValue": "资料确认"
            },
            "dtStart": {
              "type": "string",
              "description": "第二条日程开始时间。",
              "sampleValue": "11:00"
            },
            "dtEnd": {
              "type": "string",
              "description": "第二条日程结束时间。",
              "sampleValue": "11:20"
            },
            "eventLocation": {
              "type": "string",
              "description": "第二条日程地点。",
              "sampleValue": "线上会议"
            }
          },
          {
            "entityId": {
              "type": "string",
              "description": "第三条日程项唯一标识符。",
              "sampleValue": "evt-sub-003"
            },
            "title": {
              "type": "string",
              "description": "第三条日程标题。",
              "sampleValue": "会场彩排"
            },
            "dtStart": {
              "type": "string",
              "description": "第三条日程开始时间。",
              "sampleValue": "14:00"
            },
            "dtEnd": {
              "type": "string",
              "description": "第三条日程结束时间。",
              "sampleValue": "15:00"
            },
            "eventLocation": {
              "type": "string",
              "description": "第三条日程地点。",
              "sampleValue": "主会场"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_time.png",
      "description": "彩色时间图标，适合在当下日程卡片中标识会议时间。"
    },
    {
      "src": "resources/base/media/local_fill.svg",
      "description": "定位语义图标，适合标识会议地点，需放在浅色图标底板上。"
    }
  ]
}

